// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import {
  facetCounts,
  facetIndex,
  facetModel,
  RANGE_VALUE,
} from "../../../main/frontend/graph-explorer/graph-facets.ts";
import { sparqlNodeId } from "../../../main/frontend/graph-explorer/rdf-terms.ts";
import { BLANK_VALUE_ID } from "../../../main/frontend/graph-explorer/facet-queries.ts";

const EX = "http://example.org/";
const XSD = "http://www.w3.org/2001/XMLSchema#";
const RDF_TYPE = "http://www.w3.org/1999/02/22-rdf-syntax-ns#type";
const LABEL = "http://www.w3.org/2000/01/rdf-schema#label";
const BORN = `${EX}birthDate`;
const KNOWS = `${EX}knows`;
const person = (name) => ({ id: `${EX}${name}`, label: name, kind: "iri", types: [] });
const dateId = (value) => sparqlNodeId({ type: "literal", value, datatype: `${XSD}date` });
const cell = (...values) => ({ values, complete: true });

const people = ["alice", "bob", "carol", "dave", "erin"].map(person);
// Only names and one knows link are loaded; the birthdays exist only in the repository.
const edges = [{ id: "e1", source: `${EX}alice`, predicate: KNOWS, label: "knows", target: `${EX}bob` }];
const repository = new Map([
  [`${EX}alice`, { predicates: new Map([[BORN, cell(dateId("1990-04-01"))], [KNOWS, cell(`${EX}bob`, `${EX}zed`)], [LABEL, cell("x")]]), predicatesComplete: true }],
  [`${EX}bob`, { predicates: new Map([[BORN, cell(dateId("1985-09-12"))]]), predicatesComplete: true }],
  [`${EX}carol`, { predicates: new Map([[BORN, cell(dateId("2001-01-30"))], [`${EX}pet`, cell(BLANK_VALUE_ID)]]), predicatesComplete: true }],
  [`${EX}dave`, { predicates: new Map([[BORN, cell(dateId("1979-12-24"))]]), predicatesComplete: true }],
  [`${EX}erin`, { predicates: new Map([[BORN, { values: [dateId("1995-06-15")], complete: false }]]), predicatesComplete: true }],
]);
const input = (extra = {}) => ({
  nodes: people,
  edges,
  nodeById: new Map(people.map((node) => [node.id, node])),
  typesOf: () => [],
  hiddenPredicates: new Set([RDF_TYPE, LABEL]),
  repositoryValues: (id) => repository.get(id),
  labelOf: (id) => ({ [BORN]: "birth date", [`${EX}zed`]: "Zed" })[id],
  ...extra,
});
const facet = (model, id) => model.facets.find((candidate) => candidate.id === id);

test("predicates and values that are not loaded become filters from the repository", () => {
  const model = facetCounts(facetIndex(input()), new Map());
  const born = facet(model, BORN);
  assert.ok(born, "birthdays are a filter although none is loaded");
  assert.equal(born.label, "birth date", "a predicate that is not loaded takes its label from the repository");
  assert.equal(born.coverage, 5);
  assert.equal(born.range?.kind, "date", "unloaded dates still make a range");
  const knows = facet(model, KNOWS);
  assert.deepEqual(knows.values.map((value) => [value.label, value.count]).sort(), [["Zed", 1], ["bob", 1]],
    "a loaded value and the same value from the repository count once; an unloaded IRI uses its label");
  assert.ok(!facet(model, LABEL), "hidden predicates stay hidden");
  assert.deepEqual(facet(model, `${EX}pet`).values.map((value) => value.label), ["Blank node"]);
});

test("a date range selects the nodes born in it, numerically, without listing value ids", () => {
  const index = facetIndex(input());
  const selection = new Map([[BORN, new Set([RANGE_VALUE])]]);
  const ranges = new Map([[BORN, { from: "1984-01-01", to: "1991-12-31" }]]);
  const model = facetCounts(index, selection, { ranges });
  assert.deepEqual([...model.matches].sort(), [`${EX}alice`, `${EX}bob`]);
});

test("a node whose cell is incomplete matches when the server confirms it", () => {
  const index = facetIndex(input());
  const selection = new Map([[BORN, new Set([dateId("2010-01-01")])]]);
  assert.equal(facetCounts(index, selection).matches.size, 0);
  assert.deepEqual(facet(facetCounts(index, new Map()), BORN).incomplete, 1, "one node has more values than were loaded");
  const confirmed = facetCounts(index, selection, { confirmed: new Map([[BORN, new Set([`${EX}erin`])]]) });
  assert.deepEqual([...confirmed.matches], [`${EX}erin`]);
});

test("without repository values the model is what it was", () => {
  const plain = { ...input(), repositoryValues: undefined, selection: new Map() };
  const viaModel = facetModel(plain);
  const viaParts = facetCounts(facetIndex(plain), new Map());
  assert.deepEqual(viaParts.facets.map((candidate) => candidate.id), viaModel.facets.map((candidate) => candidate.id));
  assert.deepEqual([...viaParts.matches], [...viaModel.matches]);
});

test("counting for a new selection stays fast on 5,000 nodes with 20 values each", () => {
  const nodes = [];
  const values = new Map();
  for (let index = 0; index < 5000; index++) {
    const id = `${EX}n${index}`;
    nodes.push({ id, label: `n${index}`, kind: "iri", types: [] });
    const predicates = new Map();
    for (let predicate = 0; predicate < 20; predicate++)
      predicates.set(`${EX}p${predicate}`, cell(sparqlNodeId({ type: "literal", value: String((index * 7 + predicate) % 300) })));
    values.set(id, { predicates, predicatesComplete: true });
  }
  const index = facetIndex({
    nodes, edges: [], nodeById: new Map(nodes.map((node) => [node.id, node])), typesOf: () => [],
    hiddenPredicates: new Set(), repositoryValues: (id) => values.get(id),
  });
  const selection = new Map([[`${EX}p3`, new Set([sparqlNodeId({ type: "literal", value: "10" })])]]);
  facetCounts(index, selection);
  const times = [];
  for (let run = 0; run < 5; run++) {
    const started = performance.now();
    facetCounts(index, selection);
    times.push(performance.now() - started);
  }
  times.sort((left, right) => left - right);
  assert.ok(times[2] < 80, `median ${times[2].toFixed(1)} ms`);
});
